// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        // Precondition: any caller is allowed, but we use vm.assume for valid callers (not address(0) to avoid issues)
        vm.assume(caller != address(0));

        // Give the contract some balance to make the transfer meaningful
        vm.deal(address(c), 1 ether);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll as the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", address(this)));

        // The rule: if the call succeeded (no revert), the balance should be zero only if caller == owner
        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(caller == c.owner() ? balanceAfter == 0 : balanceAfter == balanceBefore);
        } else {
            // If it reverted, balance should be unchanged
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

