pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Give the contract some ether
        vm.deal(address(c), 1 ether);

        // Record contract balance before call
        uint256 balanceBefore = address(c).balance;

        // Prepare to call withdrawAll
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawAll(address)", address(0xdead)));

        // The rule: contract balance is zero iff the caller was the owner (address(this))
        bool isOwner = (caller == address(this));
        bool balanceZero = (address(c).balance == 0);
        assertTrue(isOwner == balanceZero, "Balance zero mismatch with caller permission");
    }
}

