pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient, uint256 _amount) public {
        _amount = bound(_amount, 0, 100 ether);
        vm.deal(address(c), _amount);
        uint256 initBalance = address(this).balance;
        uint256 initContractBalance = address(c).balance;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        if (ok) {
            assertTrue(address(this).balance == initBalance + initContractBalance);
        } else {
            assertTrue(address(c).balance == initContractBalance);
        }
    }
}

