import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.deal(address(c), amount);
        if (recipient == address(c)) vm.assume(false); // avoid self-transfer issues
        uint256 balanceBefore = address(c).balance;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

